    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: #121a2e;
      --panel-border: #293454;
      --text: #edf2ff;
      --muted: #a9b5d1;
      --accent: #6ea8fe;
      --accent-strong: #8bb8ff;
      --success: #8ce99a;
      --danger: #ff8787;
      --shadow: 0 20px 50px rgba(0, 0, 0, 0.35);
    }

