      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Arial, Helvetica, sans-serif;
      background:
        radial-gradient(circle at top, #172340 0%, transparent 35%),
        linear-gradient(180deg, #060910 0%, var(--bg) 100%);
      color: var(--text);
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 24px;
    }

    .quiz-shell {
      width: min(100%, 760px);
      background: rgba(18, 26, 46, 0.96);
      border: 1px solid var(--panel-border);
      border-radius: 20px;
      box-shadow: var(--shadow);
      padding: 32px;
    }

    h1 {
      margin: 0 0 12px;
      font-size: clamp(1.8rem, 4vw, 2.4rem);
    }

    .intro {
      margin: 0 0 28px;
      color: var(--muted);
      line-height: 1.5;
    }

    .form-field {
      background: rgba(255, 255, 255, 0.03);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 16px;
      padding: 20px;
      margin-bottom: 18px;
    }

    fieldset {
      border: 0;
      margin: 0;
      padding: 0;
      min-width: 0;
    }

    legend {
      font-size: 1.08rem;
      font-weight: 700;
      margin-bottom: 8px;
    }

    .help-text {
      margin: 0 0 14px;
      color: var(--muted);
      font-size: 0.96rem;
      line-height: 1.45;
    }

    .option-list {
      display: grid;
      gap: 12px;
    }

    .option {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 14px 16px;
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 12px;
      background: rgba(255, 255, 255, 0.02);
      cursor: pointer;
      transition: border-color 0.2s ease, background-color 0.2s ease, transform 0.2s ease;
    }

    .option:hover {
      border-color: rgba(110, 168, 254, 0.5);
      background: rgba(110, 168, 254, 0.08);
      transform: translateY(-1px);
    }

    input[type="checkbox"] {
      width: 1.1rem;
      height: 1.1rem;
      accent-color: var(--accent);
      flex: 0 0 auto;
    }

    button {
      border: 0;
      border-radius: 999px;
      background: linear-gradient(135deg, var(--accent), var(--accent-strong));
      color: #08111f;
      font-weight: 700;
      font-size: 1rem;
      padding: 14px 22px;
      cursor: pointer;
      transition: transform 0.2s ease, filter 0.2s ease;
    }

    button:hover {
      transform: translateY(-1px);
      filter: brightness(1.05);
    }

    button:focus-visible,
    input[type="checkbox"]:focus-visible,
    .option:has(input[type="checkbox"]:focus-visible) {
      outline: 3px solid #ffffff;
      outline-offset: 3px;
    }

    .result {
      min-height: 1.5rem;
      margin-top: 18px;
      font-weight: 700;
    }

    .result.success {
      color: var(--success);
    }

    .result.error {
      color: var(--danger);
