      button {
        border-color: ButtonText;
      }

      .quiz-shell,
      .form-field,
      .option {
        background: Canvas;
        color: CanvasText;
      }

      button {
        background: ButtonFace;
        color: ButtonText;
      }

      .help-text,
      .intro {
        color: CanvasText;
      }
    }
  </style>
</head>
<body>
  <main class="quiz-shell">
    <h1>Computer Languages Quiz</h1>
