    <form id="quiz-form">
      <div class="form-field">
        <fieldset aria-describedby="question-1-help">
          <legend>1. Which of these are commonly used for web browsers?</legend>
          <p id="question-1-help" class="help-text">Select every language that developers regularly use to build browser-based experiences.</p>
          <div class="option-list">
            <label class="option"><input type="checkbox" name="q1" value="JavaScript">JavaScript</label>
            <label class="option"><input type="checkbox" name="q1" value="HTML">HTML</label>
            <label class="option"><input type="checkbox" name="q1" value="CSS">CSS</label>
            <label class="option"><input type="checkbox" name="q1" value="COBOL">COBOL</label>
          </div>
        </fieldset>
      </div>

      <div class="form-field">
        <fieldset>
          <legend>2. Which languages are typically considered compiled languages?</legend>
          <div class="option-list">
            <label class="option"><input type="checkbox" name="q2" value="C++">C++</label>
            <label class="option"><input type="checkbox" name="q2" value="Rust">Rust</label>
            <label class="option"><input type="checkbox" name="q2" value="Python">Python</label>
            <label class="option"><input type="checkbox" name="q2" value="Go">Go</label>
          </div>
        </fieldset>
      </div>

      <div class="form-field">
        <fieldset>
          <legend>3. Which of these languages are often used for data analysis or scientific computing?</legend>
          <div class="option-list">
            <label class="option"><input type="checkbox" name="q3" value="Python">Python</label>
            <label class="option"><input type="checkbox" name="q3" value="R">R</label>
            <label class="option"><input type="checkbox" name="q3" value="Julia">Julia</label>
            <label class="option"><input type="checkbox" name="q3" value="PHP">PHP</label>
          </div>
        </fieldset>
      </div>

      <button type="submit">Submit Quiz</button>
      <p id="result" class="result" aria-live="polite"></p>
    </form>
  </main>

  <script>
    const quizForm = document.getElementById("quiz-form");
    const result = document.getElementById("result");

    const answers = {
      q1: ["JavaScript", "HTML", "CSS"],
      q2: ["C++", "Rust", "Go"],
      q3: ["Python", "R", "Julia"]
    };

    function getSelections(name) {
      return Array.from(document.querySelectorAll(`input[name="${name}"]:checked`))
        .map((input) => input.value)
        .sort();
    }

    function isCorrectSelection(selected, correct) {
      return selected.length === correct.length && selected.every((value, index) => value === correct[index]);
    }

    quizForm.addEventListener("submit", (event) => {
      event.preventDefault();

      let score = 0;

      Object.entries(answers).forEach(([question, correctAnswers]) => {
        const selected = getSelections(question);
        const sortedCorrectAnswers = [...correctAnswers].sort();

        if (isCorrectSelection(selected, sortedCorrectAnswers)) {
          score += 1;
        }
      });

      result.className = "result " + (score === Object.keys(answers).length ? "success" : "error");
      result.textContent = `You got ${score} out of ${Object.keys(answers).length} questions correct.`;
    });
  </script>
</body>
</html>
